 function getEvolutionSpecialForm(
   name: string,
 ): EvolutionSpecialForm | null {
   if (/(?:^|-)mega(?:-|$)/.test(name)) return 'Mega Evolution';
   if (/(?:^|-)gmax(?:-|$)/.test(name)) return 'Gigantamax';
